// src/api/tmdb.js 에 추가할 함수 예시

// 영화 상세 정보 + 출연진/감독 정보를 동시에 가져오는 함수
export const getMovieDetailsWithCredits = async (movieId) => {
  const TMDB_API_KEY = '7b62a6d8f7b7f0e49308f8c6ceb4cf80'; 
  const KOBIS_API_KEY = 'b5b0cb84dc79a8589d6d6bee3a960b00'; 

  try {
    // 상세 정보와 크레딧(출연진/감독)을 병렬로 동시에 호출하여 로딩 속도 극대화
    const [detailRes, creditsRes] = await Promise.all([
      fetch(`${BASE_URL}/movie/${movieId}?api_key=${API_KEY}&language=ko-KR`),
      fetch(`${BASE_URL}/movie/${movieId}/credits?api_key=${API_KEY}&language=ko-KR`)
    ]);

    const movieData = await detailRes.json();
    const creditsData = await creditsRes.json();

    // 감독 찾기
    const director = creditsData.crew?.find(person => person.job === 'Director')?.name || '정보 없음';

    // 주요 등장인물 (상위 5명)
    const cast = creditsData.cast?.slice(0, 5).map(actor => actor.name).join(', ') || '정보 없음';

    return {
      ...movieData,
      director,
      cast,
      overview: movieData.overview || '등록된 줄거리가 없습니다.'
    };
  } catch (error) {
    console.error('영화 상세 데이터 로드 실패:', error);
    return null;
  }
};
